INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$An asset has a carrying amount of ₱1,200,000 and recoverable amount of ₱1,050,000. What impairment loss is recognized?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱100,000", "is_correct": false}, {"label": "B", "text": "₱150,000", "is_correct": true}, {"label": "C", "text": "₱1,050,000", "is_correct": false}, {"label": "D", "text": "₱2,250,000", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The impairment loss equals carrying amount less recoverable amount: ₱1,200,000 − ₱1,050,000 = ₱150,000.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"An impairment loss should be recognized whenever recoverable amount is below carrying amount."$q$);

