VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$A natural resource has a depletion base of ₱9,000,000 and estimated production of 3,000,000 units. What is the depletion rate per unit?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱0.33", "is_correct": false}, {"label": "B", "text": "₱3.00", "is_correct": true}, {"label": "C", "text": "₱6.00", "is_correct": false}, {"label": "D", "text": "₱27.00", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The units-of-output method allocates the depletion base over estimated productive output. ₱9,000,000 ÷ 3,000,000 units = ₱3 per unit.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"New depletion rate/unit = Remaining depletion cost Remaining revised estimate of the productive output"$q$);

