VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$Under PAS 20, when is a government grant recognized?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Only after all conditions have been completed", "is_correct": false}, {"label": "B", "text": "When there is reasonable assurance the conditions will be met and the grant received", "is_correct": true}, {"label": "C", "text": "When management intends to apply for the grant", "is_correct": false}, {"label": "D", "text": "When the grant is approved but receipt is uncertain", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Recognition requires reasonable assurance both of compliance with the conditions and of receipt of the grant.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Government grant, including nonmonetary grant at fair value, shall be recognized when there is reasonable assurance that: The entity will comply with the conditions attaching to the grant."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$A government grant relates to a depreciable asset. Over what basis is the grant-related income recognized?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Entirely when cash is received", "is_correct": false}, {"label": "B", "text": "Over the periods and in proportion to depreciation", "is_correct": true}, {"label": "C", "text": "Only upon disposal", "is_correct": false}, {"label": "D", "text": "Directly in share capital", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A grant related to a depreciable asset is recognized over the periods and in proportion to depreciation of the related asset.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Grant related to depreciable asset shall be recognized as income over the periods and in proportion to the depreciation of the related asset."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
