VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$What is a qualifying asset under PAS 23?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "An asset ready for immediate use", "is_correct": false}, {"label": "B", "text": "An asset that takes a substantial period to get ready for intended use or sale", "is_correct": true}, {"label": "C", "text": "Any current asset", "is_correct": false}, {"label": "D", "text": "Any financial asset", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A qualifying asset necessarily takes a substantial period of time to become ready for intended use or sale.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"A qualifying asset is an asset that necessarily takes a substantial period of time to get ready for the intended use or sale."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$Borrowing costs directly attributable to a qualifying asset are generally treated how?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Expensed immediately", "is_correct": false}, {"label": "B", "text": "Capitalized as part of the asset's cost", "is_correct": true}, {"label": "C", "text": "Recognized in OCI", "is_correct": false}, {"label": "D", "text": "Deducted from equity", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Directly attributable borrowing costs are capitalized as part of the cost of a qualifying asset.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"If the borrowing is directly attributable to the acquisition, construction or production of a qualifying asset, the borrowing cost is required to be capitalized as cost of the asset."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$A qualifying asset is financed by specific borrowing. Interest incurred is ₱500,000 and temporary investment income is ₱30,000. How much borrowing cost is eligible for capitalization?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱30,000", "is_correct": false}, {"label": "B", "text": "₱470,000", "is_correct": true}, {"label": "C", "text": "₱500,000", "is_correct": false}, {"label": "D", "text": "₱530,000", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$For specific borrowing, eligible capitalization is actual borrowing cost less investment income from temporary investment: ₱500,000 − ₱30,000 = ₱470,000.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The amount eligible for capitalization on that asset shall be determined as the actual borrowing cost incurred during the period less any investment income"$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$Which event is required before capitalization of borrowing costs can begin?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The asset is completely finished.", "is_correct": false}, {"label": "B", "text": "The entity incurs expenditures for the asset.", "is_correct": true}, {"label": "C", "text": "The asset is sold.", "is_correct": false}, {"label": "D", "text": "The loan is fully repaid.", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Capitalization begins only when all three conditions are present, including expenditures, borrowing costs, and activities necessary to prepare the asset.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The capitalization of borrowing costs as part of the cost of a qualifying asset shall commence when the following three conditions are present: When the entity incurs expenditures for the asset."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$During what circumstance should capitalization of borrowing costs be suspended?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Any period of normal construction activity", "is_correct": false}, {"label": "B", "text": "Extended periods when active development is interrupted", "is_correct": true}, {"label": "C", "text": "Whenever interest rates change", "is_correct": false}, {"label": "D", "text": "Whenever temporary investment income is earned", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Capitalization is suspended during extended periods in which active development is interrupted. Normal substantial technical or administrative work does not ordinarily cause suspension.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Capitalization of borrowing costs shall be suspended during extended periods in which active development is interrupted."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$When does capitalization of borrowing costs cease?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "When the first expenditure is incurred", "is_correct": false}, {"label": "B", "text": "When substantially all activities necessary to prepare the asset are complete", "is_correct": true}, {"label": "C", "text": "When construction begins", "is_correct": false}, {"label": "D", "text": "When interest is paid", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Capitalization ceases when substantially all activities necessary to prepare the qualifying asset for intended use or sale are complete.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Capitalization of borrowing costs shall cease when substantially all the activities necessary to prepare the qualifying asset for the intended use or sale is complete."$q$);

