VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$What does agricultural activity involve?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Only selling agricultural products", "is_correct": false}, {"label": "B", "text": "Managing biological transformation of biological assets", "is_correct": true}, {"label": "C", "text": "Manufacturing farm equipment", "is_correct": false}, {"label": "D", "text": "Leasing agricultural land", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Agricultural activity involves management of biological transformation for sale, agricultural produce, or additional biological assets.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Agricultural activity is the management by an entity of the biological transformation of biological assets for sale, into agricultural produce, or into additional biological assets."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$Which two conditions must generally exist to recognize a purchased or self-created intangible asset at cost?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Future benefits are probable and cost is reliably measurable.", "is_correct": true}, {"label": "B", "text": "Fair value is always available and useful life exceeds 20 years.", "is_correct": false}, {"label": "C", "text": "The asset is marketable and debt-financed.", "is_correct": false}, {"label": "D", "text": "The asset is internally generated and has a legal title.", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Recognition requires probable future economic benefits and reliable measurement of cost.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"It is probable that the future economic benefits that are attributable to the asset will flow to the enterprise. The cost of the asset can be measured reliably."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$How are subsequent expenditures on an intangible asset generally treated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Capitalized automatically", "is_correct": false}, {"label": "B", "text": "Recognized as expense when incurred", "is_correct": true}, {"label": "C", "text": "Recognized in OCI", "is_correct": false}, {"label": "D", "text": "Added to goodwill", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The PDF states that subsequent expenditure after purchase or completion is recognized as expense when incurred.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Subsequent expenditure on an intangible asset after its purchase or completion should be recognized as an expense when it is incurred."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$If an entity cannot distinguish the research phase from the development phase of an internal project, how is the expenditure treated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "As development expenditure", "is_correct": false}, {"label": "B", "text": "As research expenditure", "is_correct": true}, {"label": "C", "text": "As goodwill", "is_correct": false}, {"label": "D", "text": "As inventory", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$When the phases cannot be distinguished, the PDF requires treating the expenditure as if it were incurred during the research phase.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"If an entity cannot distinguish the research phase from the development phase of an internal project to create an intangible asset, the entity treats the expenditure on that project as if it were incurred in the research phase only."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
