VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$An operating segment reports ₱12 million of combined external and intersegment revenue, while combined segment revenue is ₱100 million. Does it meet the PDF's revenue threshold for separate reporting?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "No, because the threshold is 15%.", "is_correct": false}, {"label": "B", "text": "No, because the threshold is 20%.", "is_correct": false}, {"label": "C", "text": "Yes, because revenue is at least 10%.", "is_correct": true}, {"label": "D", "text": "Yes, because revenue is at least 25%.", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$₱12 million ÷ ₱100 million = 12%, which exceeds the 10% quantitative threshold.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"Its reported revenue, including both sales to external customers and intersegment sales or transfers, is 10 percent (10%) or more of the combined revenue"$q$);

