INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Financial Accounting and Reporting$q$ LIMIT 1), $q$A company reports net income of ₱5,000,000 and cumulative preference dividends of ₱400,000 for the current year. What amount is attributable to ordinary shareholders before considering the weighted-average share denominator?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱4,400,000", "is_correct": false}, {"label": "B", "text": "₱4,600,000", "is_correct": true}, {"label": "C", "text": "₱5,000,000", "is_correct": false}, {"label": "D", "text": "₱5,400,000", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$For basic EPS, current-year cumulative preference dividends are deducted from net income whether declared or not: ₱5,000,000 − ₱400,000 = ₱4,600,000.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"If the preference share is cumulative, the preference dividend for the current year only is deducted from the net income, whether such dividend is declared or not."$q$);

