VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Under the acquisition method, which amount generally represents the consideration transferred in a business combination?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The acquiree's carrying amount of net assets", "is_correct": false}, {"label": "B", "text": "The acquisition-date fair value of assets transferred, liabilities incurred, and equity interests issued by the acquirer", "is_correct": true}, {"label": "C", "text": "The acquiree's historical cost of identifiable assets", "is_correct": false}, {"label": "D", "text": "The acquiree's book value of equity", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The acquisition method measures consideration transferred at acquisition-date fair value. The other choices use carrying or historical amounts rather than the acquisition-date measurement basis.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"consideration transferred in a business combination is measured at fair value"

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$In a business combination achieved in stages, how is the acquirer's previously held equity interest generally treated at the acquisition date?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "It remains at its original carrying amount", "is_correct": false}, {"label": "B", "text": "It is ignored in determining goodwill", "is_correct": false}, {"label": "C", "text": "It is remeasured to fair value, with the resulting gain or loss recognized as appropriate", "is_correct": true}, {"label": "D", "text": "It is measured at the acquiree's book value", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A step acquisition requires the previously held interest to be remeasured to acquisition-date fair value. Keeping it at carrying amount would fail to apply the acquisition-date measurement basis.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"previously held equity interest is remeasured to fair value at the acquisition date"

