VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$A parent owns 80% of a subsidiary. If the subsidiary reports ₱500,000 of profit for the period, what is the parent's share of that profit before other consolidation adjustments?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱100,000", "is_correct": false}, {"label": "B", "text": "₱400,000", "is_correct": true}, {"label": "C", "text": "₱500,000", "is_correct": false}, {"label": "D", "text": "₱625,000", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The parent's 80% interest gives it an ₱400,000 share of the subsidiary's ₱500,000 profit. The remaining ₱100,000 belongs to NCI.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"profit or loss is attributed to the owners of the parent and to the non-controlling interests"

