INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Which statement best describes non-controlling interest in consolidated financial statements?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "It is always presented as a liability", "is_correct": false}, {"label": "B", "text": "It represents the portion of a subsidiary's equity not attributable to the parent", "is_correct": true}, {"label": "C", "text": "It is eliminated entirely on consolidation", "is_correct": false}, {"label": "D", "text": "It is recognized only when the subsidiary is liquidated", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$NCI represents equity interests in a subsidiary that are not attributable, directly or indirectly, to the parent. It remains within consolidated equity rather than being eliminated as a liability.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"non-controlling interest is the equity in a subsidiary not attributable, directly or indirectly, to a parent"

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Parent Co. sells inventory to Subsidiary Co. at a profit, and some of that inventory remains unsold at year-end. What consolidation adjustment is required?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Recognize the intercompany profit immediately", "is_correct": false}, {"label": "B", "text": "Eliminate the unrealized intercompany profit included in ending inventory", "is_correct": true}, {"label": "C", "text": "Increase consolidated inventory by the intercompany profit", "is_correct": false}, {"label": "D", "text": "Transfer the profit to NCI", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Consolidated financial statements treat the group as a single economic entity, so profit on inventory that remains within the group is unrealized and must be eliminated.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"unrealized profit on intercompany inventory transactions is eliminated"

