VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$A parent sells equipment to its subsidiary at a gain. The equipment remains within the group. Which consolidation treatment is appropriate?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Retain the gain because the sale was legally completed", "is_correct": false}, {"label": "B", "text": "Eliminate the intercompany gain and adjust depreciation to the amount that would have been recognized without the intercompany sale", "is_correct": true}, {"label": "C", "text": "Recognize the gain in OCI", "is_correct": false}, {"label": "D", "text": "Eliminate only the equipment's accumulated depreciation", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The group cannot recognize an internal gain before the asset is effectively sold outside the group. Depreciation must also be based on the group's original carrying amount.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"gains arising from transactions between group entities are eliminated"

