VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$When a parent and subsidiary have intercompany bonds, what is the consolidation objective?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Report the bonds as external investments and debt", "is_correct": false}, {"label": "B", "text": "Eliminate the intercompany asset, liability, and related income and expense", "is_correct": true}, {"label": "C", "text": "Reclassify the bonds as equity", "is_correct": false}, {"label": "D", "text": "Recognize all intercompany interest as consolidated revenue", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Intercompany debt does not represent an obligation to or claim against an outside party. The related bond balances and income or expense are therefore eliminated in consolidation.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"intercompany balances and transactions, including intercompany debt and interest, are eliminated"

