VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$A foreign-currency monetary item is outstanding at reporting date. Under the usual closing-rate approach, which rate is used for translation?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Historical rate only", "is_correct": false}, {"label": "B", "text": "Closing rate", "is_correct": true}, {"label": "C", "text": "Average rate for the entire life of the item", "is_correct": false}, {"label": "D", "text": "Rate at the date of original invoice only", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Monetary items denominated in foreign currency are translated at the closing rate at the reporting date. Using the original transaction rate would ignore subsequent exchange-rate changes.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"foreign currency monetary items shall be translated using the closing rate"

