VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Parent Co. owns 75% of Subsidiary Co. and sells inventory with a ₱100,000 profit. If 40% of the inventory remains unsold at year-end, what unrealized profit must be eliminated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱25,000", "is_correct": false}, {"label": "B", "text": "₱40,000", "is_correct": true}, {"label": "C", "text": "₱60,000", "is_correct": false}, {"label": "D", "text": "₱100,000", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The unrealized portion is ₱100,000 × 40% = ₱40,000. The ownership percentage does not reduce the elimination amount for a downstream sale.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"unrealized profits on transactions between group entities are eliminated in full"

