VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Which statement best describes the relationship between functional currency and presentation currency?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "They must always be the same", "is_correct": false}, {"label": "B", "text": "Functional currency reflects the primary economic environment, while presentation currency is the currency in which financial statements are presented", "is_correct": true}, {"label": "C", "text": "Presentation currency determines functional currency", "is_correct": false}, {"label": "D", "text": "Functional currency is always the parent's currency", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The two concepts serve different purposes: functional currency reflects economic substance, while presentation currency is the currency selected for financial statement presentation.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"functional currency is the currency of the primary economic environment in which the entity operates"

