VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$A parent acquires 80% of a subsidiary for ₱8 million. The fair value of the subsidiary's identifiable net assets is ₱9 million, and NCI is measured at ₱2.1 million. What is goodwill?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱0.9 million", "is_correct": false}, {"label": "B", "text": "₱1.1 million", "is_correct": true}, {"label": "C", "text": "₱1.9 million", "is_correct": false}, {"label": "D", "text": "₱2.1 million", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Goodwill = ₱8.0 million + ₱2.1 million − ₱9.0 million = ₱1.1 million. This uses the full-goodwill calculation when NCI is measured at fair value.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"goodwill is the excess of the consideration transferred and the amount of any NCI over the net identifiable assets"

