VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Advanced Financial Accounting and Reporting$q$ LIMIT 1), $q$Which statement about consolidated financial statements is correct?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "They present the parent and subsidiaries as separate unrelated entities", "is_correct": false}, {"label": "B", "text": "They present the parent and subsidiaries as a single economic entity", "is_correct": true}, {"label": "C", "text": "They exclude all subsidiaries", "is_correct": false}, {"label": "D", "text": "They include only the parent's assets", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Consolidated financial statements combine the parent and controlled subsidiaries as a single economic entity and eliminate intragroup effects.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"consolidated financial statements present the assets, liabilities, equity, income, expenses and cash flows of the parent and its subsidiaries as those of a single economic entity"

