VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$Which item is classified as a manufacturing cost?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Selling commission", "is_correct": false}, {"label": "B", "text": "Direct materials", "is_correct": true}, {"label": "C", "text": "Office salary", "is_correct": false}, {"label": "D", "text": "Income tax expense", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Direct materials are one of the three manufacturing-cost classifications. Selling commissions and office salaries are period costs.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Manufacturing costs are classified as (1) direct materials, (2) direct labor, or (3) manufacturing overhead."

