INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$A small amount of glue used in production cannot be economically traced to individual products. How should it be classified?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Direct materials", "is_correct": false}, {"label": "B", "text": "Direct labor", "is_correct": false}, {"label": "C", "text": "Manufacturing overhead", "is_correct": true}, {"label": "D", "text": "Selling expense", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$Materials that cannot be economically traced to individual products are treated as indirect materials and included in manufacturing overhead.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Cannot be traced because their physical association with the finished product is too small in terms of cost."

