INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$A manufacturer has beginning finished goods of ₱40,000, cost of goods manufactured of ₱250,000, and ending finished goods of ₱55,000. What is cost of goods sold?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱155,000", "is_correct": false}, {"label": "B", "text": "₱195,000", "is_correct": false}, {"label": "C", "text": "₱235,000", "is_correct": true}, {"label": "D", "text": "₱345,000", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$COGS = beginning finished goods + COGM − ending finished goods = ₱40,000 + ₱250,000 − ₱55,000 = ₱235,000.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Manufacturers compute cost of goods sold by adding the beginning finished goods inventory to the cost of goods manufactured and subtracting the ending finished goods inventory."

