INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$Beginning WIP is ₱80,000, current manufacturing costs are ₱420,000, and ending WIP is ₱65,000. What is cost of goods manufactured?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "₱275,000", "is_correct": false}, {"label": "B", "text": "₱355,000", "is_correct": false}, {"label": "C", "text": "₱435,000", "is_correct": true}, {"label": "D", "text": "₱565,000", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$COGM = beginning WIP + current manufacturing costs − ending WIP = ₱80,000 + ₱420,000 − ₱65,000 = ₱435,000.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Companies then subtract the ending work in process from the total cost of work in process to find the cost of goodsmanufactured."

