VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$The internal rate of return is the interest rate that causes:$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Maximum accounting profit", "is_correct": false}, {"label": "B", "text": "The present value of the investment to equal the present value of expected net cash flows", "is_correct": true}, {"label": "C", "text": "Payback to equal one year", "is_correct": false}, {"label": "D", "text": "Profitability index to equal zero", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$IRR is the rate at which the present value of expected cash flows equals the investment.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The internal rate of return is the interest rate that will cause the present value of the expenditure to equal the present value of the expected net annual cash flows."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Management Services$q$ LIMIT 1), $q$Which statement correctly describes WACC?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "It is the cost of inventory financing only", "is_correct": false}, {"label": "B", "text": "It is the overall cost of capital from all organization financing sources", "is_correct": true}, {"label": "C", "text": "It is the cost of common stock only", "is_correct": false}, {"label": "D", "text": "It is the amount of dividends paid", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$WACC represents the overall cost of capital from the organization's financing sources.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The weighted average cost of capital (WACC) represents the overall cost of capital from all organization financing sources."$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An assurance practitioner is engaged to issue a written conclusion intended to increase users’ confidence in evaluated information. Which service is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Financial accounting service", "is_correct": false}, {"label": "B", "text": "Tax compliance service", "is_correct": false}, {"label": "C", "text": "Management-only consulting service", "is_correct": false}, {"label": "D", "text": "Assurance engagement", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines an assurance engagement as one that expresses a conclusion designed to enhance intended users’ confidence. A tax or consulting service does not itself provide that assurance conclusion."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An audit client asks what level of assurance an ordinary financial statement audit provides. What should the auditor explain?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Moderate assurance", "is_correct": false}, {"label": "B", "text": "No assurance", "is_correct": false}, {"label": "C", "text": "High, but not absolute assurance", "is_correct": true}, {"label": "D", "text": "Absolute assurance", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF describes reasonable assurance as high but not absolute. Moderate assurance is associated with limited assurance or review engagements."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Why can an assurance practitioner generally not provide absolute assurance?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Because criteria are never used", "is_correct": false}, {"label": "B", "text": "Because judgment, testing, internal-control limitations, and persuasive rather than conclusive evidence remain", "is_correct": true}, {"label": "C", "text": "Because auditors are prohibited from examining evidence", "is_correct": false}, {"label": "D", "text": "Because assurance reports never contain conclusions", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF lists judgment, testing, inherent limitations of internal control, and persuasive rather than conclusive evidence as reasons absolute assurance is generally unattainable. The other choices contradict the framework."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A proposed assurance subject matter cannot be consistently evaluated or measured against suitable criteria. What requirement is missing?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Appropriateness of the subject matter", "is_correct": true}, {"label": "B", "text": "Independence of intended users", "is_correct": false}, {"label": "C", "text": "Compilation expertise", "is_correct": false}, {"label": "D", "text": "An agreed-upon procedure", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF requires subject matter to be identifiable, capable of consistent evaluation and measurement against suitable criteria, and capable of being subjected to evidence-gathering procedures."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Users need criteria that allow reasonably consistent evaluation by similarly qualified practitioners in similar circumstances. Which criterion is being described?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Neutrality", "is_correct": false}, {"label": "B", "text": "Completeness", "is_correct": false}, {"label": "C", "text": "Understandability", "is_correct": false}, {"label": "D", "text": "Reliability", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Reliable criteria allow reasonably consistent evaluation or measurement under similar circumstances. Neutrality concerns freedom from bias, while completeness concerns omission of relevant factors."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Which attitude must a practitioner use when planning and performing an assurance engagement to obtain sufficient appropriate evidence?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Management representation", "is_correct": false}, {"label": "B", "text": "Commercial awareness", "is_correct": false}, {"label": "C", "text": "Professional skepticism", "is_correct": true}, {"label": "D", "text": "Advocacy", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Professional skepticism is expressly required and includes a questioning mind, alertness to possible misstatement, and critical assessment of evidence."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A CPA performs an agreed-upon procedures engagement and reports only factual findings from procedures agreed with the parties. What assurance is expressed?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Absolute assurance", "is_correct": false}, {"label": "B", "text": "No assurance", "is_correct": true}, {"label": "C", "text": "Reasonable assurance", "is_correct": false}, {"label": "D", "text": "Limited assurance", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF states that agreed-upon procedures reports factual findings and express no assurance. Users assess the findings themselves."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Which statement correctly distinguishes quality-control policies from procedures?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Policies state objectives and goals; procedures are steps used to accomplish and monitor them", "is_correct": true}, {"label": "B", "text": "Policies are audit tests; procedures are financial reporting standards", "is_correct": false}, {"label": "C", "text": "Policies apply only to listed entities; procedures apply only to private entities", "is_correct": false}, {"label": "D", "text": "Policies are optional; procedures are mandatory only for reviews", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF expressly distinguishes policies as objectives/goals and procedures as the steps used to accomplish and monitor those policies."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Under PSQC 1, what must Philippine CPA firms establish and implement?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A separate tax department", "is_correct": false}, {"label": "B", "text": "An internal audit department", "is_correct": false}, {"label": "C", "text": "A government review committee", "is_correct": false}, {"label": "D", "text": "A system of quality control", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF states that PSQC 1 requires CPA firms to establish and implement a system of quality control. It does not require the other structures as stated."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Two CPA firms differ in size, organization, geographic dispersion, and network status. What does the PDF say about their quality-control systems?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Only network firms need quality control", "is_correct": false}, {"label": "B", "text": "Smaller firms are exempt", "is_correct": false}, {"label": "C", "text": "Their nature and extent may vary because of those factors", "is_correct": true}, {"label": "D", "text": "They must use identical policies and procedures", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF expressly lists size, nature of practice, operating characteristics, organization, geographic dispersion, cost-benefit considerations, and network status as factors affecting the nature and extent."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A firm’s leadership establishes an internal culture recognizing that quality is essential in engagements. Which quality-control element is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Engagement performance", "is_correct": false}, {"label": "B", "text": "Leadership responsibilities for quality within the firm", "is_correct": true}, {"label": "C", "text": "Monitoring", "is_correct": false}, {"label": "D", "text": "Human resources", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF places the internal culture and ultimate responsibility for quality under leadership responsibilities. Monitoring and human resources are separate elements."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A firm monitors whether it has sufficient personnel with the capabilities, competence, and ethical commitment needed for engagements. Which quality-control element is involved?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Human resources", "is_correct": true}, {"label": "B", "text": "Leadership", "is_correct": false}, {"label": "C", "text": "Monitoring", "is_correct": false}, {"label": "D", "text": "Acceptance and continuance", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF assigns sufficient personnel with capabilities, competence, and ethical commitment to human resources. Monitoring instead evaluates whether quality controls operate effectively."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A firm periodically inspects completed engagements to evaluate whether quality controls remain relevant, adequate, effective, and complied with. Which element is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Human resources", "is_correct": false}, {"label": "B", "text": "Engagement performance", "is_correct": false}, {"label": "C", "text": "Acceptance and continuance", "is_correct": false}, {"label": "D", "text": "Monitoring", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF describes ongoing evaluation and inspection of selected completed engagements as part of monitoring. Engagement performance concerns performing engagements in accordance with standards."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Which statement correctly distinguishes PSAs from the firm’s system of quality control?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "They are identical terms", "is_correct": false}, {"label": "B", "text": "SQC replaces PSAs for financial statement audits", "is_correct": false}, {"label": "C", "text": "PSAs relate to individual audits, while SQC relates to the firm’s professional activities as a whole", "is_correct": true}, {"label": "D", "text": "PSAs apply to the whole firm, while SQC applies only to one audit", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF directly distinguishes the two by engagement-level versus firm-wide scope. They are complementary, not interchangeable."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Management intentionally alters accounting records to mislead financial statement users. Which type of fraud is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Non-sampling risk", "is_correct": false}, {"label": "B", "text": "Fraudulent financial reporting", "is_correct": true}, {"label": "C", "text": "Misappropriation of assets", "is_correct": false}, {"label": "D", "text": "Sampling risk", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Fraudulent financial reporting consists of intentional misstatements or omissions intended to deceive financial statement users. Misappropriation concerns theft or misuse of assets."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An employee steals inventory for personal benefit. Which fraud category applies?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Misappropriation of assets", "is_correct": true}, {"label": "B", "text": "Fraudulent financial reporting", "is_correct": false}, {"label": "C", "text": "Management override", "is_correct": false}, {"label": "D", "text": "Control risk", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines misappropriation of assets as theft of assets and gives stealing inventory as an example. It is distinct from financial reporting fraud."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Management is under pressure to inflate earnings to secure bank financing. Which fraud-risk factor category does this represent?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Opportunity", "is_correct": false}, {"label": "B", "text": "Attitudes or rationalizations", "is_correct": false}, {"label": "C", "text": "Sampling risk", "is_correct": false}, {"label": "D", "text": "Incentives or pressures", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF identifies pressure to inflate earnings to secure bank financing as an example of incentives/pressures. Opportunity concerns the ability to commit and conceal fraud."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Why is a material fraud generally harder to detect than a material error?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Errors are always corrected before audit", "is_correct": false}, {"label": "B", "text": "Auditors have no responsibility for fraud", "is_correct": false}, {"label": "C", "text": "Fraud may involve sophisticated concealment and collusion", "is_correct": true}, {"label": "D", "text": "Fraud is always committed by management", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF explains that fraud can involve sophisticated schemes designed to conceal it and may be accompanied by collusion. It does not say fraud is always management fraud."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Why does the PDF state that management fraud presents a greater risk of non-detection than employee fraud?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Employee fraud cannot involve collusion", "is_correct": false}, {"label": "B", "text": "Management can override controls and influence financial statement preparation and presentation", "is_correct": true}, {"label": "C", "text": "Employees are prohibited from committing fraud", "is_correct": false}, {"label": "D", "text": "Management has no access to accounting records", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF attributes the greater risk to management’s opportunity, ability to override controls, and influence over financial statement preparation and presentation."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An entity violates a law or regulation, whether intentionally or unintentionally. How does the PDF define this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Non-compliance", "is_correct": true}, {"label": "B", "text": "Sampling risk", "is_correct": false}, {"label": "C", "text": "Audit evidence", "is_correct": false}, {"label": "D", "text": "Materiality", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Non-compliance is defined as acts of omission or commission contrary to prevailing laws or regulations. It may be intentional or unintentional."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Who has primary responsibility for preventing, detecting, and correcting noncompliance with laws and regulations?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The external auditor", "is_correct": false}, {"label": "B", "text": "The audit committee alone", "is_correct": false}, {"label": "C", "text": "The Professional Regulatory Board of Accountancy", "is_correct": false}, {"label": "D", "text": "Management", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF places responsibility for compliance with laws and regulations on management. The auditor considers compliance because noncompliance may materially affect financial statements."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An audit team learns that a client is under government investigation and has paid unusual fines. What should these facts be treated as?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Evidence requiring an adverse opinion in every case", "is_correct": false}, {"label": "B", "text": "A reason to ignore the matter because auditors do not consider laws", "is_correct": false}, {"label": "C", "text": "Indications that noncompliance may have occurred", "is_correct": true}, {"label": "D", "text": "Proof that fraud occurred", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Government investigations and payment of fines or penalties are specifically listed as indications that noncompliance may have occurred. They are indicators, not automatic proof of fraud or a particular opinion."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$During acceptance of a prospective client, the predecessor auditor is contacted. Which topic is specifically appropriate to discuss?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The client’s future tax rate", "is_correct": false}, {"label": "B", "text": "Reasons for the change of auditors", "is_correct": true}, {"label": "C", "text": "The successor’s planned audit opinion", "is_correct": false}, {"label": "D", "text": "The predecessor’s personal finances", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF lists reasons for the change, client integrity, and significant disagreements as matters to discuss with the predecessor. The successor should not seek a predetermined opinion."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An existing audit client has undergone a major ownership change. What does the PDF say about continuance procedures?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Acceptance and continuance should be evaluated upon such a change", "is_correct": true}, {"label": "B", "text": "No further evaluation is necessary until the next five-year cycle", "is_correct": false}, {"label": "C", "text": "Only tax compliance needs reconsideration", "is_correct": false}, {"label": "D", "text": "The auditor must automatically resign", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF says existing clients should be evaluated once a year or when specified events occur, including changes in management, directors, or ownership. It does not mandate automatic withdrawal."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A CPA firm discovers a threat to independence during an audit. What does the PDF require?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Ignore it unless management complains", "is_correct": false}, {"label": "B", "text": "Replace the financial statements", "is_correct": false}, {"label": "C", "text": "Issue an adverse opinion automatically", "is_correct": false}, {"label": "D", "text": "Identify, evaluate, and respond to the threat", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The material expressly requires the CPA firm or auditor to identify, evaluate, and respond to threats to independence. An adverse opinion does not automatically follow."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A prospective audit client operates in an industry in which the CPA lacks expertise. What should the CPA consider before accepting?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Issuing a disclaimer before starting", "is_correct": false}, {"label": "B", "text": "Using only management’s knowledge", "is_correct": false}, {"label": "C", "text": "Obtaining knowledge of matters related to the industry to establish competence", "is_correct": true}, {"label": "D", "text": "Accepting immediately because expertise is optional", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF says the auditor should determine whether the required competence exists and, if industry expertise is lacking, obtain knowledge of relevant matters. It does not say expertise is irrelevant."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
