VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Who has primary responsibility for the fairness of representations made in the financial statements?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The Board of Accountancy", "is_correct": false}, {"label": "B", "text": "Management", "is_correct": true}, {"label": "C", "text": "The independent auditor", "is_correct": false}, {"label": "D", "text": "The audit committee alone", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The audit framework places responsibility for the financial statements with management. The auditor provides an independent opinion rather than preparing or owning management’s representations."

