INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Internal control is best described in the PDF as what?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A guarantee against fraud", "is_correct": false}, {"label": "B", "text": "An external audit performed by management", "is_correct": false}, {"label": "C", "text": "A set of financial reporting standards", "is_correct": false}, {"label": "D", "text": "A process designed, implemented, and maintained to provide reasonable assurance about objectives", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines internal control as a process effected by governance, management, and personnel to provide reasonable assurance about objectives. It is not a guarantee."

