INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Management refuses to provide a written representation that the auditor considers necessary. What reporting consequence does the PDF identify?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The refusal constitutes a scope limitation and may result in a qualified opinion or disclaimer", "is_correct": true}, {"label": "B", "text": "An automatic unmodified opinion", "is_correct": false}, {"label": "C", "text": "An automatic adverse opinion", "is_correct": false}, {"label": "D", "text": "No consequence if oral representations exist", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF treats refusal to provide necessary written representations as a scope limitation, resulting in a qualified opinion or disclaimer depending on circumstances. Oral representations do not automatically cure it."

