INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A Type I subsequent event provides evidence about a condition that existed at the balance-sheet date. What is the usual financial statement treatment?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Disclosure only", "is_correct": false}, {"label": "B", "text": "No action is ever needed", "is_correct": false}, {"label": "C", "text": "Immediate disclaimer", "is_correct": false}, {"label": "D", "text": "Adjustment", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF distinguishes events providing evidence of conditions existing at period end as those requiring adjustment. Events arising afterward are generally disclosure events."

