INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Analytical procedures at the overall review stage reveal unexpected relationships that management cannot explain satisfactorily. What should the auditor most likely do?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Perform additional audit procedures to investigate", "is_correct": true}, {"label": "B", "text": "Immediately issue an adverse opinion", "is_correct": false}, {"label": "C", "text": "Ignore the relationships", "is_correct": false}, {"label": "D", "text": "Withdraw without further work", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF’s question set indicates that unexplained unexpected relationships call for additional audit procedures. The finding alone does not dictate an adverse opinion."

