INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Who is primarily responsible for identifying and disclosing related parties and related-party transactions?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The external auditor alone", "is_correct": false}, {"label": "B", "text": "The SEC", "is_correct": false}, {"label": "C", "text": "The FRSC", "is_correct": false}, {"label": "D", "text": "Management", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF’s question bank states that responsibility rests with management. The auditor evaluates identification and disclosure but does not assume management’s primary responsibility."

