INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor is unable to obtain sufficient appropriate evidence because of a significant scope limitation, but the possible effects are material and not pervasive. Which opinion is indicated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Unmodified opinion", "is_correct": false}, {"label": "B", "text": "Compilation report", "is_correct": false}, {"label": "C", "text": "Qualified opinion", "is_correct": true}, {"label": "D", "text": "Adverse opinion", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF’s reporting matrix states that inability to obtain sufficient appropriate evidence with material but not pervasive effects results in a qualified opinion. Adverse applies to material and pervasive misstatement, not a scope limitation."

