INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor concludes the financial statements contain a material misstatement that is pervasive. Which modified opinion is appropriate?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Unmodified opinion", "is_correct": false}, {"label": "B", "text": "Adverse opinion", "is_correct": true}, {"label": "C", "text": "Qualified opinion", "is_correct": false}, {"label": "D", "text": "Disclaimer of opinion", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF states that material and pervasive financial statement misstatements lead to an adverse opinion. A qualified opinion applies when the matter is material but not pervasive."

