INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$The auditor cannot obtain sufficient appropriate evidence and the possible effects are both material and pervasive. Which opinion is indicated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Disclaimer of opinion", "is_correct": true}, {"label": "B", "text": "Qualified opinion", "is_correct": false}, {"label": "C", "text": "Adverse opinion", "is_correct": false}, {"label": "D", "text": "Unmodified opinion", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF’s matrix distinguishes scope limitations from misstatements: material and pervasive inability to obtain sufficient appropriate evidence leads to a disclaimer. Adverse is for known pervasive misstatement."

