INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A financial statement departure from the applicable framework is material and pervasive. Which opinion applies?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Disclaimer of opinion", "is_correct": false}, {"label": "B", "text": "Unmodified opinion", "is_correct": false}, {"label": "C", "text": "Adverse opinion", "is_correct": true}, {"label": "D", "text": "Qualified opinion", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF states that an adverse opinion is used when the auditor does not believe the financial statements are fairly presented, corresponding to material and pervasive misstatement."

