INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$The auditor cannot determine whether the financial statements are fairly presented because sufficient evidence is unavailable. Which modified opinion may apply when the effects are pervasive?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Unmodified opinion", "is_correct": false}, {"label": "B", "text": "Disclaimer of opinion", "is_correct": true}, {"label": "C", "text": "Adverse opinion", "is_correct": false}, {"label": "D", "text": "Qualified opinion", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"A disclaimer is used when the auditor cannot obtain sufficient appropriate evidence and the possible effects are material and pervasive. Adverse is used for known material and pervasive misstatement."

