INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor tests fewer than 100% of population items, with every sampling unit having a chance of selection, to form a conclusion about the population. What is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Analytical review", "is_correct": false}, {"label": "B", "text": "Inspection", "is_correct": false}, {"label": "C", "text": "Audit sampling", "is_correct": true}, {"label": "D", "text": "Non-sampling risk", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines audit sampling as applying procedures to less than 100% of items such that all sampling units have a chance of selection. Non-sampling risk is an error source unrelated to sample size."

