INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$A sample-based conclusion differs from what the auditor would conclude after examining the entire population. Which risk is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Inherent risk", "is_correct": false}, {"label": "B", "text": "Sampling risk", "is_correct": true}, {"label": "C", "text": "Non-sampling risk", "is_correct": false}, {"label": "D", "text": "Control risk", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Sampling risk is specifically the possibility that a sample-based conclusion differs from the conclusion that would result from examining the entire population. Non-sampling risk arises for other reasons."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor reaches an erroneous conclusion because an inappropriate procedure was used, not because the sample was too small. Which risk is illustrated?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Non-sampling risk", "is_correct": true}, {"label": "B", "text": "Sampling risk", "is_correct": false}, {"label": "C", "text": "Risk of incorrect rejection", "is_correct": false}, {"label": "D", "text": "Risk of assessing control risk too low", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF says non-sampling risk arises from factors unrelated to sample size, including inappropriate procedures or misinterpreting evidence. Sampling risk is specifically related to using a sample."

