INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$What does statistical sampling require that nonstatistical sampling does not necessarily require?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A professional judgment-free process", "is_correct": false}, {"label": "B", "text": "Testing every item", "is_correct": false}, {"label": "C", "text": "No measurement of sampling risk", "is_correct": false}, {"label": "D", "text": "Random selection and use of probability theory to evaluate sample results", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF defines statistical sampling by random selection and probability theory, including measurement of sampling risk. Nonstatistical sampling uses judgment to determine sample size and evaluate results."

