INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor determines sample size using professional judgment rather than a mathematical calculation and evaluates the results judgmentally. What approach is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Attribute sampling only", "is_correct": false}, {"label": "B", "text": "Variables sampling only", "is_correct": false}, {"label": "C", "text": "Nonstatistical sampling", "is_correct": true}, {"label": "D", "text": "Statistical sampling", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF defines nonstatistical sampling as judgment-based sample sizing and judgmental evaluation of results. Statistical sampling uses mathematical methods."

