INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor estimates the peso amount or numerical quantity of a population during substantive testing of account balances. Which sampling type is typically used?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Variables sampling", "is_correct": true}, {"label": "B", "text": "Attribute sampling", "is_correct": false}, {"label": "C", "text": "Control-risk sampling", "is_correct": false}, {"label": "D", "text": "Qualitative sampling", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The PDF states that variables sampling estimates numerical quantity and is typically used in substantive testing of account balances because it deals with peso balances."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$In a test of controls, sample results suggest the control deviation rate is lower than the true population rate. What sampling risk has occurred?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Risk of assessing control risk too high", "is_correct": false}, {"label": "B", "text": "Risk of incorrect rejection", "is_correct": false}, {"label": "C", "text": "Risk of incorrect acceptance", "is_correct": false}, {"label": "D", "text": "Risk of assessing control risk too low", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF defines this risk as assessing control risk below its true level because the sample indicates a lower deviation rate than actually exists. This may cause inappropriate reliance on controls."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$In substantive testing, the sample indicates no material misstatement, but the population actually contains a material misstatement. Which risk is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Risk of assessing control risk too high", "is_correct": false}, {"label": "B", "text": "Sampling efficiency risk", "is_correct": false}, {"label": "C", "text": "Risk of incorrect acceptance", "is_correct": true}, {"label": "D", "text": "Risk of incorrect rejection", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"Incorrect acceptance occurs when sample results lead the auditor to conclude the account is not materially misstated when it actually is. This threatens audit effectiveness."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$In substantive testing, sample results indicate a material misstatement, but the population is actually not materially misstated. Which risk is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Non-sampling risk", "is_correct": false}, {"label": "B", "text": "Risk of incorrect rejection", "is_correct": true}, {"label": "C", "text": "Risk of incorrect acceptance", "is_correct": false}, {"label": "D", "text": "Risk of assessing control risk too low", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"Incorrect rejection occurs when the sample mistakenly indicates a material misstatement when none exists. The PDF associates this with additional work and reduced efficiency."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$In a test of controls, sample results indicate a higher deviation rate than actually exists, causing the auditor to conclude controls cannot be relied upon. Which risk is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Risk of assessing control risk too high", "is_correct": true}, {"label": "B", "text": "Risk of assessing control risk too low", "is_correct": false}, {"label": "C", "text": "Risk of incorrect acceptance", "is_correct": false}, {"label": "D", "text": "Risk of incorrect rejection", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF defines risk of assessing control risk too high as concluding that control risk is higher than it really is based on the sample. This generally affects efficiency by causing more work."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$In a test of controls, what is the maximum deviation rate the auditor is willing to accept without changing the planned reliance on internal control?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Expected deviation rate", "is_correct": false}, {"label": "B", "text": "Tolerable error", "is_correct": false}, {"label": "C", "text": "Expected error", "is_correct": false}, {"label": "D", "text": "Tolerable deviation rate", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines tolerable deviation rate as the maximum rate of deviation acceptable without changing the control-risk assessment or planned reliance. Expected deviation rate is the auditor’s estimate."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor estimates the deviation rate expected to exist in a population before testing a control. What term applies?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Tolerable error", "is_correct": false}, {"label": "B", "text": "Sampling risk", "is_correct": false}, {"label": "C", "text": "Expected deviation rate", "is_correct": true}, {"label": "D", "text": "Tolerable deviation rate", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Expected deviation rate is the auditor’s best estimate of the rate of deviation in the population. Tolerable deviation rate is the maximum acceptable rate."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor sets the maximum total error in a population that will be accepted in a substantive procedure. What term applies?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Expected error", "is_correct": false}, {"label": "B", "text": "Tolerable error", "is_correct": true}, {"label": "C", "text": "Tolerable deviation rate", "is_correct": false}, {"label": "D", "text": "Expected deviation rate", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Tolerable error applies to substantive procedures and represents the maximum total error the auditor is willing to accept. Tolerable deviation rate applies to tests of controls."

