INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$Is audit sampling mandatory for every audit procedure according to the PDF?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "No; the auditor may examine all items or select specific items instead", "is_correct": true}, {"label": "B", "text": "Yes; every audit procedure requires a sample", "is_correct": false}, {"label": "C", "text": "Yes; only statistical sampling is permitted", "is_correct": false}, {"label": "D", "text": "No; auditors may never sample", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF expressly says audit sampling is not a required part of every audit procedure. The auditor may select all items, specific items, or use sampling as appropriate."

