INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor examines records or documents or physically examines an asset. Which audit procedure is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Observation", "is_correct": false}, {"label": "B", "text": "Inquiry", "is_correct": false}, {"label": "C", "text": "Recalculation", "is_correct": false}, {"label": "D", "text": "Inspection", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Inspection involves examining records or documents or physically examining an asset. Observation instead involves watching a process being performed."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor watches an employee perform a process to evaluate how the process operates. Which audit procedure is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Reperformance", "is_correct": false}, {"label": "B", "text": "Confirmation", "is_correct": false}, {"label": "C", "text": "Observation", "is_correct": true}, {"label": "D", "text": "Inspection", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Observation consists of viewing a process or procedure being performed by others. Reperformance means independently executing a procedure or control originally performed by the entity."

