INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor checks the mathematical accuracy of a client document or record. Which procedure is being performed?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Observation", "is_correct": false}, {"label": "B", "text": "Recalculation", "is_correct": true}, {"label": "C", "text": "Reperformance", "is_correct": false}, {"label": "D", "text": "Inquiry", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Recalculation is checking mathematical accuracy manually or electronically. Reperformance involves independently carrying out procedures or controls."

