INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor independently performs a control that was originally performed by client personnel. Which procedure is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Reperformance", "is_correct": true}, {"label": "B", "text": "Recalculation", "is_correct": false}, {"label": "C", "text": "Inspection", "is_correct": false}, {"label": "D", "text": "Inquiry", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Reperformance means carrying out procedures or controls that were originally performed by the entity. Recalculation is limited to mathematical accuracy."

