INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor seeks information from knowledgeable financial or nonfinancial persons inside or outside the entity. Which procedure is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Observation", "is_correct": false}, {"label": "B", "text": "Inspection", "is_correct": false}, {"label": "C", "text": "Recalculation", "is_correct": false}, {"label": "D", "text": "Inquiry", "is_correct": true}]$j$::jsonb, $q$D$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The PDF defines inquiry as seeking information from knowledgeable persons, whether financial or nonfinancial and whether inside or outside the entity."

