INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor evaluates financial information by studying plausible relationships among financial and nonfinancial data. Which procedure is this?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Confirmation", "is_correct": false}, {"label": "B", "text": "Reperformance", "is_correct": false}, {"label": "C", "text": "Analytical procedures", "is_correct": true}, {"label": "D", "text": "Inspection", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Analytical procedures are evaluations based on plausible relationships among financial and nonfinancial data. They often compare recorded amounts with independent expectations."

