INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$An auditor starts with source documents and traces forward into accounting records to test whether transactions have been recorded. Which assertion is primarily addressed?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Classification", "is_correct": false}, {"label": "B", "text": "Completeness", "is_correct": true}, {"label": "C", "text": "Existence", "is_correct": false}, {"label": "D", "text": "Occurrence only", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF states that tracing from source documents to accounting records tests completeness and helps identify understatement errors. Vouching works in the opposite direction."

