INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Theory$q$ LIMIT 1), $q$For financial statement presentation and disclosure, the auditor asks whether all disclosures that should have been included are present. Which assertion applies?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Completeness", "is_correct": true}, {"label": "B", "text": "Occurrence and rights and obligations", "is_correct": false}, {"label": "C", "text": "Classification and understandability", "is_correct": false}, {"label": "D", "text": "Accuracy and valuation", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The PDF’s presentation/disclosure assertions identify completeness as inclusion of all disclosures that should have been included. The other assertions address different disclosure characteristics."

