INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A customer confirms a balance lower than the client's ledger because an older invoice was already settled but the payment was posted to another invoice. What audit procedure should the auditor perform next?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Ignore the difference because the customer replied", "is_correct": false}, {"label": "B", "text": "B. Trace the customer's payment to the bank deposit and remittance details", "is_correct": true}, {"label": "C", "text": "C. Send a positive confirmation to the supplier", "is_correct": false}, {"label": "D", "text": "D. Recompute depreciation on the customer's equipment", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Tracing the payment and its posting identifies whether the customer's cash settlement was misapplied; merely accepting the confirmation does not resolve the ledger error.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Accounts receivable confirmation letters were sent to the customers. Customer B P36,000 Invoice dated 8/20 was already settled. Investigation revealed that payment was erroneously posted against account for an invoice dated 12/20 for the same amount."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A customer disputes an invoice because goods had not been received at year-end and the terms were FOB destination. Which procedure is most directly relevant?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Inspect the customer's subsequent receipt of the goods and shipping terms", "is_correct": true}, {"label": "B", "text": "B. Confirm the client's bank loan", "is_correct": false}, {"label": "C", "text": "C. Recalculate the client's depreciation expense", "is_correct": false}, {"label": "D", "text": "D. Inspect the client's stock transfer agent", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The dispute turns on whether the sale was complete at year-end, so the auditor should inspect shipment terms and subsequent receipt.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The difference was due to the invoice dated 12/30. Goods have not yet been received by Customer C as of December 31. Terms of sale is FOB Destination."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A positive confirmation for a receivable receives no reply. Based on the file, which customer-specific fact makes follow-up particularly important?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. The customer is under liquidation and the receivable is definitely uncollectible", "is_correct": true}, {"label": "B", "text": "B. The customer has a credit balance", "is_correct": false}, {"label": "C", "text": "C. The customer purchased PPE", "is_correct": false}, {"label": "D", "text": "D. The customer paid a dividend", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$A nonresponse from a customer under liquidation requires the auditor to investigate collectibility rather than treat the silence as confirmation.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Customer F No reply Customer F is under liquidation and the amount receivable from the company is deemed definitely uncollectible."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The auditor is testing the allowance for doubtful accounts. Which procedure is most appropriate for the receivables classified by age?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Apply the stated collectibility percentages to the aging categories and investigate unusual balances", "is_correct": true}, {"label": "B", "text": "B. Confirm only the bank balance", "is_correct": false}, {"label": "C", "text": "C. Vouch all receivables to PPE invoices", "is_correct": false}, {"label": "D", "text": "D. Reconcile share capital to the transfer agent", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file provides collectibility percentages by age, so an aging-based recalculation and investigation of unusual items directly tests valuation.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Age Collectibility % 30 days and below 99% 31-60 days 98% 61-90 days 95% 91-120 days 90% Over 120 days 50%."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$An auditor wants evidence about whether a receivable outstanding at year-end is collectible. Which procedure is most directly relevant?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Inspect cash collected from the customer after year-end", "is_correct": true}, {"label": "B", "text": "B. Inspect the client's petty cash count", "is_correct": false}, {"label": "C", "text": "C. Recompute building depreciation", "is_correct": false}, {"label": "D", "text": "D. Inspect treasury shares", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Subsequent cash collection provides direct evidence that the year-end receivable was realized.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"The credit balance of ABC Co. was for an overpayment from the customer. The company delivered additional merchandise to ABC Co. on January 3, 2026 to cover such overstatement."

---$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The general ledger does not reconcile with the receivables subsidiary ledger after identified errors have been corrected. What should the auditor do first?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Investigate the remaining difference before accepting a plug", "is_correct": true}, {"label": "B", "text": "B. Automatically record it as sales", "is_correct": false}, {"label": "C", "text": "C. Confirm the client's investments", "is_correct": false}, {"label": "D", "text": "D. Write off every old receivable", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file contemplates a remaining difference only after corrections; the auditor should investigate it before an adjustment is made.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"In the event that the Accounts Receivable general ledger does not reconcile with the subsidiary ledger after corrections are made and the difference cannot be located, you have come into an agreement with the client to adjust the control to the sum of the subsidiaries as miscellaneous income or expense."

---$q$);

