VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A December 30 sale is disputed because the customer did not receive the goods by December 31 and the terms are FOB destination. Which evidence should the auditor inspect?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Shipping documents and the terms of sale", "is_correct": true}, {"label": "B", "text": "B. The client's depreciation schedule", "is_correct": false}, {"label": "C", "text": "C. The client's dividend register", "is_correct": false}, {"label": "D", "text": "D. The bank's loan agreement", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Shipping documents and FOB terms determine whether the sale belongs in the year under audit.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Goods have not yet been received by Customer C as of December 31. Terms of sale is FOB Destination."

