INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The auditor identifies a receivable classified as over six months old. Which procedure best tests its valuation using the client's stated methodology?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Determine whether the balance falls into a category requiring a 50%, 90%, or 100% collection assessment", "is_correct": true}, {"label": "B", "text": "B. Confirm the client's share capital", "is_correct": false}, {"label": "C", "text": "C. Inspect receiving reports for inventory", "is_correct": false}, {"label": "D", "text": "D. Recalculate leasehold improvements", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file gives separate collection assessments for over-six-month balances, so the auditor should apply those classifications to the specific receivable.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"Definitely uncollectible P72,000 Doubtful (estimated to be 50% collectible) 36,000 Apparently good but slow (estimated to be 90% collectible) 120,000 Total P228,000."

