INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A credit balance appears in the receivables subsidiary ledger. What should the auditor investigate before treating it as an ordinary receivable?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Whether it represents an overpayment, posting error, or customer advance", "is_correct": true}, {"label": "B", "text": "B. Whether the customer owns PPE", "is_correct": false}, {"label": "C", "text": "C. Whether the customer has issued bonds", "is_correct": false}, {"label": "D", "text": "D. Whether the customer is a stock transfer agent", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file shows that credit balances can represent different underlying transactions, so the auditor must inspect the source of the credit.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"The credit balance of GHI Inc. was a cash advance for a delivery to be made on January 15, 2026."

