VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The auditor finds that the recorded allowance differs from the amount supported by the receivables aging. What substantive procedure should be performed?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Recalculate the required allowance using the stated aging assumptions and propose the adjustment", "is_correct": true}, {"label": "B", "text": "B. Confirm only accounts payable", "is_correct": false}, {"label": "C", "text": "C. Count petty cash", "is_correct": false}, {"label": "D", "text": "D. Inspect the client's building title", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file supplies the aging and estimated collection rates needed to independently recompute the allowance.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"It was estimated that 1% of accounts receivable under 1 month is doubtful of collection while 2% of accounts receivable under 1-6 months are expected to require an allowance for doubtful accounts."

