VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A purchase is FOB shipping point, shipped before year-end, but received after year-end. What should the auditor inspect to determine whether the item belongs in year-end inventory?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Shipping date and freight terms", "is_correct": true}, {"label": "B", "text": "B. Customer confirmation", "is_correct": false}, {"label": "C", "text": "C. Dividend declaration", "is_correct": false}, {"label": "D", "text": "D. Lease agreement", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$FOB shipping point and shipment date determine when title passes for the cutoff test in the file.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Goods costing P16,500 were delivered to ABC on January 4, 2026. The invoice for these goods was received and recorded on January 10, 2026. The invoice showed the shipment was made on December 29, 2025, FOB shipping point."

