VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$Goods received on consignment are included in the physical count. What audit procedure should address this item?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Inspect the consignment terms and remove goods that are not owned by the client from inventory", "is_correct": true}, {"label": "B", "text": "B. Confirm the client's customers", "is_correct": false}, {"label": "C", "text": "C. Recompute payroll", "is_correct": false}, {"label": "D", "text": "D. Inspect share subscriptions", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The file distinguishes consigned goods from owned inventory, so the auditor should verify ownership and adjust the count for items not owned by the client.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Goods valued at P51,000 were received from a vendor under a consignment term during the year. These goods were included in the physical count."

