VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$Goods owned by the client are on consignment with a customer but were excluded from the physical count. What should the auditor do?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Obtain evidence of the goods held by the consignee and include them in the client's inventory", "is_correct": true}, {"label": "B", "text": "B. Exclude them because they are not on the client's premises", "is_correct": false}, {"label": "C", "text": "C. Record them as accounts payable", "is_correct": false}, {"label": "D", "text": "D. Treat them as sales automatically", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Ownership remains relevant even when goods are held by another party, so the auditor should obtain evidence of the third-party inventory.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Goods costing P50,000 are on consignment with a customer. These goods were not included in the physical count on December 31, 2025."

