VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$A receiving report for a December 27 FOB shipping-point shipment was not recorded until January 2026. What should the auditor do?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Trace the shipment and invoice and propose recording the purchase and related payable in 2025", "is_correct": true}, {"label": "B", "text": "B. Ignore it because the invoice was recovered in January", "is_correct": false}, {"label": "C", "text": "C. Record it as a 2026 sale", "is_correct": false}, {"label": "D", "text": "D. Charge it to share premium", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$The shipment occurred before year-end under FOB shipping point, so the audit cutoff should capture the liability and inventory in 2025.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Receiving Report No. 2634 is for a shipment made on December 27, 2025 under FOB shipping point. The related invoice amounting to P12,500 was misplaced and was recovered only on January 5, 2026 and was recorded thereafter."

