INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$Goods were shipped FOB destination on December 31 and received January 5, while the client recorded the sale in 2025. What should the auditor inspect?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Shipping terms and the customer's receipt date", "is_correct": true}, {"label": "B", "text": "B. The customer's share capital", "is_correct": false}, {"label": "C", "text": "C. The client's bank transfer schedule", "is_correct": false}, {"label": "D", "text": "D. The client's patent register", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$For a destination shipment, the shipping terms and receipt date are the key evidence for determining whether the sale and inventory cutoff is correct.$q$, NULL, NULL, NULL, FALSE, $q$hard$q$, $q$"ABC recorded as a 2025 sale a P64,300 shipment of goods to a customer on December 31, 2025, FOB destination. This shipment of goods costing P37,500 was received by the customer on January 5, 2026."

