VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The auditor wants to test whether the client's inventory cutoff control operated consistently. Which procedure is a test of controls?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Inspect a sample of receiving reports around year-end for evidence of required cutoff review and authorization", "is_correct": true}, {"label": "B", "text": "B. Recalculate the entire ending inventory balance", "is_correct": false}, {"label": "C", "text": "C. Independently confirm every customer balance", "is_correct": false}, {"label": "D", "text": "D. Recompute all depreciation", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Inspecting evidence that the prescribed cutoff control was performed tests operation of the control rather than directly determining the financial statement balance.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The last receiving report used and recorded for the current year by the company is Receiving Report No. 2635."

