VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Auditing Practice$q$ LIMIT 1), $q$The client sends accounts receivable confirmations as part of its control process. Which procedure tests the control rather than the year-end balance directly?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A. Inspect evidence that confirmations were prepared, authorized, mailed, and followed up for a sample of customers", "is_correct": true}, {"label": "B", "text": "B. Independently confirm every receivable", "is_correct": false}, {"label": "C", "text": "C. Recalculate depreciation", "is_correct": false}, {"label": "D", "text": "D. Inspect inventory receiving reports", "is_correct": false}]$j$::jsonb, $q$A$q$, $q$Inspecting evidence that the confirmation process operated is a control test; independently confirming balances is a substantive procedure.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Accounts receivable confirmation letters were sent to the customers."

