VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Taxation$q$ LIMIT 1), $q$What is the primary purpose of taxation?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "To regulate all private contracts", "is_correct": false}, {"label": "B", "text": "To raise revenue for governmental needs", "is_correct": true}, {"label": "C", "text": "To replace police power", "is_correct": false}, {"label": "D", "text": "To guarantee private profits", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The PDF identifies raising revenue for governmental needs as the primary purpose. The tempting alternative A is a secondary/regulatory purpose, not the primary one.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The primary purpose of taxation is to raise revenue for governmental needs."

