VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Taxation$q$ LIMIT 1), $q$Which taxation theory describes taxes as the government's lifeblood, without which government would be paralyzed?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Sumptuary theory", "is_correct": false}, {"label": "B", "text": "Symbiotic doctrine", "is_correct": false}, {"label": "C", "text": "Lifeblood theory", "is_correct": true}, {"label": "D", "text": "Power-to-destroy theory", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$The source expressly identifies the lifeblood theory with the government's need for taxes to operate. The symbiotic doctrine concerns the reciprocal relationship between State and taxpayer.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Which theory in taxation states that without taxes, a government would be paralyzed for lack of power to activate and operate it, resulting in its destruction?"

