INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$Marco issued a check that was dishonored for insufficient funds. The check was presented 75 days after its date. What evidentiary presumption arises under BP Blg. 22?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Knowledge of insufficiency is conclusively presumed", "is_correct": false}, {"label": "B", "text": "Knowledge of insufficiency is prima facie presumed", "is_correct": true}, {"label": "C", "text": "Knowledge of insufficiency cannot be presumed", "is_correct": false}, {"label": "D", "text": "Only intent to defraud is presumed", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$Presentment within 90 days creates prima facie evidence of the drawer's knowledge of insufficient funds. The presumption is not conclusive.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The making, drawing and issuance of a check payment of which is refused by the drawee because of insufficient funds or credit with such bank, when presented within ninety (90) days"$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$After receiving notice that his check was dishonored, Ramon paid the full amount to the holder on the fourth banking day. What is the effect under BP Blg. 22?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "He remains liable because payment must be made within three calendar days", "is_correct": false}, {"label": "B", "text": "He remains liable because payment must be made before presentment", "is_correct": false}, {"label": "C", "text": "He is not liable under BP Blg. 22 because payment was made within five banking days", "is_correct": true}, {"label": "D", "text": "He is automatically liable but the penalty is reduced", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$Payment or full arrangements within five banking days after notice constitutes a statutory defense. The period is measured in banking days.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"Such maker or drawer will not be liable if he pays the holder thereof the amount due thereon, or makes arrangements for payment in full"$q$);

