VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$A drawee bank dishonors a check because of insufficient funds. Which fact must it expressly state in the notice of dishonor?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "That the drawer acted fraudulently", "is_correct": false}, {"label": "B", "text": "That the account was closed", "is_correct": false}, {"label": "C", "text": "That there were no sufficient funds or credit, if that was the reason", "is_correct": true}, {"label": "D", "text": "That the drawer had knowledge of the insufficiency", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$The drawee must state the reason for dishonor, and insufficiency of funds or credit must be explicitly stated when applicable.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"Where there are no sufficient funds in or credit with such drawee bank, such fact shall always be explicitly stated in the notice of dishonor"$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$In a BP Blg. 22 prosecution, the dishonored check bears the drawee's written refusal and reason for dishonor. Which fact is prima facie established by the check?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "The drawer's fraudulent intent", "is_correct": false}, {"label": "B", "text": "The making or issuance of the check", "is_correct": true}, {"label": "C", "text": "The drawer's civil liability", "is_correct": false}, {"label": "D", "text": "The absence of a valid defense", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The dishonored check with the drawee's refusal is prima facie evidence of its making or issuance, among other matters. It does not establish fraudulent intent.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"the introduction in evidence of any unpaid and dishonored check, having the drawee's refusal to pay stamped or written thereon"$q$);

INSERT INTO quizzes (file_id, topic_id, question, format, options, answer, explanation, source_page, stem, sub_questions, is_testlet, difficulty, source_quote)
VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$Under BP Blg. 22, what does the term "credit" mean in determining whether the drawer had sufficient credit with the drawee bank?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "A consumer loan", "is_correct": false}, {"label": "B", "text": "An arrangement or understanding with the bank for payment of the check", "is_correct": true}, {"label": "C", "text": "A credit card facility only", "is_correct": false}, {"label": "D", "text": "Any outstanding bank balance", "is_correct": false}]$j$::jsonb, $q$B$q$, $q$The statute gives "credit" a specific meaning: an arrangement or understanding with the bank for payment of the check.$q$, NULL, NULL, NULL, FALSE, $q$easy$q$, $q$"The word \"credit\" as used herein shall be construed to mean an arrangement or understanding with the bank for the payment of such check."$q$);

