VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$Leo was acquitted of BP Blg. 22 because the prosecution failed to prove guilt beyond reasonable doubt. May the court still award civil damages arising from the dishonored check?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "No, because acquittal always extinguishes civil liability", "is_correct": false}, {"label": "B", "text": "No, because civil liability is dependent on criminal conviction", "is_correct": false}, {"label": "C", "text": "Yes, because acquittal based on reasonable doubt does not necessarily extinguish civil liability", "is_correct": true}, {"label": "D", "text": "Yes, but only if the drawer admits fraud", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$The material expressly states that acquittal based on lack of proof beyond reasonable doubt does not preclude civil damages.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"An acquittal based on lack of proof beyond reasonable doubt does not preclude the award of civil damages."$q$);

