VALUES (NULL, (SELECT id FROM topics WHERE name = $q$Regulatory Framework for Business Transactions$q$ LIMIT 1), $q$A person issues a worthless check in payment of a pre-existing debt. The payee claims both BP Blg. 22 and estafa. Which is correct under the material?$q$, $q$multiple_choice$q$, $j$[{"label": "A", "text": "Neither offense may exist because the debt predated the check", "is_correct": false}, {"label": "B", "text": "Only estafa necessarily exists", "is_correct": false}, {"label": "C", "text": "BP Blg. 22 liability may exist even though the check paid a pre-existing obligation", "is_correct": true}, {"label": "D", "text": "Estafa necessarily exists whenever the check is worthless", "is_correct": false}]$j$::jsonb, $q$C$q$, $q$A pre-existing obligation generally negates deceit for estafa, but BP Blg. 22 may still apply. The two offenses have different elements.$q$, NULL, NULL, NULL, FALSE, $q$medium$q$, $q$"In BP Blg. 22, even if the check is issued to pay a pre-existing obligation, there may still be liability."$q$);

